INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (27, 12, '/api/targets and target markers on /stats/difficulty', 'work', 'done', 500, '2026-10-11, authoring/server/main.py (GET /api/targets), authoring/ui/src/lib/{api,types}.ts (fetchTargets, BundleTargets), stats/DifficultyChart.svelte (target tick, approved/target label, table+tooltip), stats/CategoryChart.svelte (approved / derived share label, no marker), stats/Stats.svelte; npm run check clean, checked in headless Chrome', 'Part "Progress view" of plan 12, authoring server and UI. Needs the targets file and loader.

