INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (46, 16, 'LLM audit: audit.md, qgen audit, batch step, Audit section; batch-7 baseline', 'work', 'done', NULL, '2026-10-11, authoring/tools/prompts/audit.md, authoring/tools/qgen.py (AUDIT_SCHEMA, audit_sample, qgen audit, batch step, Audit section), authoring/RUNBOOK.md, directory.md; batch-7 baseline in plan 16', 'Part "LLM audit (a)" of plan 16: an independent second LLM reader of a seeded sample per batch.

