INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (47, 16, 'Spot-check tooling: sample, spot-checks.json, endpoints, blind review mode, audit=flagged', 'work', 'done', 640, '2026-10-11, authoring/server/spot_checks.py, authoring/server/main.py (GET/POST /api/spot-checks, sample=1, audit=flagged, audit on questions), qgen.py spot_check_problems in validate, authoring/ui review sample mode (blind, reveal, undo, problem toggles) + audit panel, directory.md; browser-checked on batch-7 with headless Chrome (approve/needs_work, reveal, undo; pool and spot-checks.json restored)', 'Part "Human spot check (b)" of plan 16. After the audit task (it provides the sample draw).

