INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (306, 52, 'providers.licence_verdict and D-entry for PD-US only', 'work', 'done', NULL, '2026-10-12, authoring/tools/providers/__init__.py, authoring/tools/qgen.py, plans/decisions.md (D-62), plans/23-media-providers.md', 'Add `licence_verdict(slot)` to `authoring/tools/providers/__init__.py`, next to `licence_kind` and `LICENCE_FIELDS` (plan 52, "Classification"). Returns `("ok" | "replace", [reasons])`, reasons as short code plus text, e.g. `off-allowlist: GFDL 1.2`.

