INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task) VALUES (432, 64, 'Docs: RUNBOOK, D-entry, QC for qgen neutralize', 'work', 'done', NULL, '2026-10-12, authoring/RUNBOOK.md (neutralize with tighten), authoring/QC.md (section ''Neutralize runs'': run=neutralize-<n>&sample=1 / &audit=flagged, qgen report --qc neutralize-<n>; --qc reads runs, no backlog gap), plans/decisions.md (D-83, D-36 related line), AGENTS.md (Pool list), plans/15-i18n.md, plans/backlog.md (B-13 tooling done), plans/project.md', 'Plan 64 task 3. Document the neutral Spanish tooling once `qgen neutralize` (plan 64 task 2) exists and the prompts (task 1''s decision) are approved.

